style.css:
@-moz-document domain("ebay.com") {
/* main eBay logo */
    a[href="/"] img,
    a[href="https://www.ebay.com/"] img,
    img[alt="eBay"] {
        content: url("https://upload.wikimedia.org/wikipedia/commons/1/11/EBay_former_logo.svg");
        object-fit: contain !important;
    }

    /* fallback for logos using a background image */
    a[href="/"] {
        background-image: url("https://upload.wikimedia.org/wikipedia/commons/1/11/EBay_former_logo.svg") !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
        background-size: contain !important;
    }

    a[href="/"] img {
        visibility: hidden !important;
    }
}
